package com.codeguardian.service;
import lombok.extern.slf4j.Slf4j; import org.springframework.stereotype.Service; import java.io.*; import java.nio.file.*; import java.util.*; import java.util.stream.Stream;
@Service @Slf4j public class GitService { private final Map<String,String> clones=new HashMap<>(); public String cloneRepository(String url,String username,String password){try{if(clones.containsKey(url)&&Files.exists(Path.of(clones.get(url))))return clones.get(url); Path tmp=Files.createTempDirectory("git_repo_"); String name=url.substring(url.lastIndexOf('/')+1).replaceAll("\\.git$",""); Path dest=tmp.resolve(name); List<String> cmd=new ArrayList<>(List.of("git","clone")); cmd.add(url); cmd.add(dest.toString()); Process p=new ProcessBuilder(cmd).redirectErrorStream(true).start(); String out=new String(p.getInputStream().readAllBytes()); if(p.waitFor()!=0)throw new RuntimeException(out); clones.put(url,dest.toString()); return dest.toString();}catch(Exception e){throw new RuntimeException("Git clone failed: "+e.getMessage(),e);}} public List<String> getFileList(String dir){try(Stream<Path> s=Files.walk(Path.of(dir))){Path root=Path.of(dir); return s.filter(Files::isRegularFile).map(root::relativize).map(Path::toString).map(x->x.replace(File.separator,"/")).toList();}catch(IOException e){throw new RuntimeException("Failed to list files",e);}} public String readFile(String file){try{return Files.readString(Path.of(file));}catch(IOException e){throw new RuntimeException("Failed to read file",e);}} }
